/**
 * Link version 1, frozen: the challenge, entry and photo shapes the channels carry.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 1 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV1.test.ts` checks the living types against it.
 */

type PrizeV1 = { type?: string; amount?: number };

type PrizeTierV1 = {
    title?: string;
    rank?: null | { min_rank?: number; max_rank?: number; type?: string };
    prizes?: PrizeV1[];
};

type MemberBoostV1 = {
    state?: 'AVAILABLE' | 'AVAILABLE_KEY' | 'LOCKED' | 'MISSED' | 'USED' | 'UNAVAILABLE' | (string & {});
    timeout?: null | number;
};

type MemberTurboV1 = {
    state?: 'WON' | 'LOCKED' | 'USED' | 'UNAVAILABLE' | (string & {}) | 'FREE' | 'IN_PROGRESS' | 'TIMER';
    mode?: 'classic' | 'snap' | (string & {});
    time_to_open?: null | number;
    max_selections?: number;
    required_selections?: number;
    turbo_unlock_amount?: number;
};

type RankingTotalV1 = {
    votes?: number;
    rank?: number;
    level?: number;
    level_name?: string;
    level_rank?: number;
    next?: number;
    percent?: number;
    exposure?: number;
    points?: number;
    guru_picks?: number;
    next_message?: string;
    benchmark?: { benchmark?: string; score?: string }[];
};

type RankingExposureV1 = { exposure_factor?: number; vote_exposure_factor?: number; vote_ratio?: number };

type EntryEnteredTimeV1 = { at: number; exact: boolean };

type RankingEntryV1 = {
    id: string;
    member_id?: string;
    votes?: number;
    rank?: number;
    views?: number;
    adult?: boolean;
    guru_pick?: boolean;
    boost?: number;
    turbo?: boolean;
    boosting?: boolean;
    boosted?: boolean;
    appEntered?: EntryEnteredTimeV1;
};

type MemberRankingV1 = {
    total?: RankingTotalV1;
    exposure?: RankingExposureV1;
    entries?: RankingEntryV1[];
    swaps?: { id: string }[];
};

type RewardResourceV1 = { type?: string; title?: string; value?: number };

type RewardsBySectionV1 = {
    claim_state?: string;
    sections?: { type?: string; name?: string; resources?: RewardResourceV1[] }[];
};

type ChallengeMemberV1 = {
    time_joined?: number;
    submit_state?: string;
    boost?: MemberBoostV1;
    turbo?: MemberTurboV1;
    ranking?: MemberRankingV1;
    rewards_by_section?: RewardsBySectionV1;
};

type TeamMatchV1 = {
    us: { name: string; votes: number };
    them: { name: string; votes: number };
    running?: boolean;
    me?:
        | null
        | { kind: 'active'; position: number; votes: number; activeSlots: number; cushion: null | number }
        | { kind: 'standby'; position: number; votes: number; activeSlots: number; votesToActive: number };
};

export type ChallengeV1 = {
    id: string | number;
    title: string;
    url?: string;
    welcome_message?: string;
    start_time: number;
    close_time: number;
    status?: string;
    type?: string;
    badge?: string;
    tags?: string[];
    entries: number;
    players: number;
    max_players?: number;
    votes?: number;
    max_photo_submits?: number;
    prizes_worth?: number;
    first_prizes?: PrizeV1[];
    achievements_and_prizes?: PrizeTierV1[];
    ranking_levels?: { [key: string]: number };
    join_coins?: number;
    image?: { id?: string; member_id?: string };
    boost_enable?: boolean;
    turbo_enable?: boolean;
    fill_enable?: boolean;
    fill_locked?: boolean;
    swap_enable?: boolean;
    swap_locked?: boolean;
    top_photo_enable?: boolean;
    guru_pick_enable?: boolean;
    top_photographer_enable?: boolean;
    levels_rank_enable?: boolean;
    new_ranking_enable?: boolean;
    member?: ChallengeMemberV1;
    boostHoldUntil?: number;
    teamMatch?: TeamMatchV1;
    dataIssues?: string[];
};

export type ActiveChallengesResponseV1 = { challenges: ChallengeV1[]; fetchFailed?: boolean; pruneUnsafe?: boolean };

export type ChallengeValuesV1 = { [key: string]: unknown };

export type EntryPinsV1 = { boost: null | string; turbo: null | string };

export type ListedPhotoV1 = {
    id: string;
    labels: string[];
    allowed: boolean;
    message: null | string;
    uploadDate: null | number;
};

export type OpenChallengeV1 = {
    suggestedPhotoIds?: string[];
    status?: 'upcoming';
    title: string;
    url?: string;
    member?: ChallengeMemberV1;
    tags?: string[];
    type?: string;
    entries: number;
    id: string | number;
    welcome_message?: string;
    start_time: number;
    close_time: number;
    badge?: string;
    players: number;
    max_players?: number;
    votes?: number;
    max_photo_submits?: number;
    prizes_worth?: number;
    first_prizes?: PrizeV1[];
    achievements_and_prizes?: PrizeTierV1[];
    ranking_levels?: { [key: string]: number };
    join_coins?: number;
    image?: { id?: string; member_id?: string };
    boost_enable?: boolean;
    turbo_enable?: boolean;
    fill_enable?: boolean;
    fill_locked?: boolean;
    swap_enable?: boolean;
    swap_locked?: boolean;
    top_photo_enable?: boolean;
    guru_pick_enable?: boolean;
    top_photographer_enable?: boolean;
    levels_rank_enable?: boolean;
    new_ranking_enable?: boolean;
    boostHoldUntil?: number;
    teamMatch?: TeamMatchV1;
    dataIssues?: string[];
    chosenOwn: string[];
    chosenOwnCount: number;
    chosenEffectiveCount: number;
};

export type ChosenAnnotationV1 = { chosenOwn: string[]; chosenOwnCount: number; chosenEffectiveCount: number };

export type PhotoStatsAnswerV1 = { id: string; votes: number; views: number; likes: number; guruPicks: number };

export type SwapCandidateV1 = { id: string; member_id: string };
